<script setup>
import { ref, computed, watch, onBeforeUnmount, nextTick } from 'vue';
import Icon from './Icon.vue';
import { data, ui, session, day, dept, doctor, labels, notify, confirmAction, book, cancelAppointment, patientAppointments, delay, newIntent, emrFields } from '../store.js';
const props = defineProps({ page: String });
const emit = defineEmits(['navigate']);
const complaint = ref('');
const triageStatus = ref('idle');
const options = ref([]);
const choice = ref(null);
const selectedDate = ref(day(1));
const selectedPeriod = ref('ALL');
const bookingResult = ref(null);
const appointmentFilter = ref('active');
const selectedRecord = ref(null);
const answer = ref('');
const chatLoading = ref(false);
const chat = ref([]);
const timerIds = [];
const chatContainer = ref(null);
watch(() => [chat.value.length, chat.value.at(-1)?.text], async () => { await nextTick(); if (chatContainer.value) chatContainer.value.scrollTop = chatContainer.value.scrollHeight; });
const questions = ['请描述您的主要不适。', '这样的情况持续多久了？', '对日常生活影响大吗？', '是否还伴有其他症状？', '是否有相关既往病史？', '是否有药物或食物过敏史？'];
const slotNames = ['主要不适', '持续时间', '影响程度', '伴随症状', '既往病史', '过敏情况'];
const login = ref({ login_name: '', password: '' });
const showPassword = ref(false);
const loginError = ref('');
const loginBusy = ref(false);
const failedLogins = ref(0);
const countdown = ref(0);
const dateTabs = computed(() => [1,2,3,4].map(n=>({date:day(n), name:n===1?'明天':n===2?'后天':new Date(day(n)+'T12:00:00').toLocaleDateString('zh-CN',{weekday:'short'}), label:day(n).slice(5).replace('-','/')})));
const filteredSchedules = computed(() => data.schedules.filter(s=>s.enabled&&s.work_date>=day()&&s.work_date===selectedDate.value&&(selectedPeriod.value==='ALL'||s.period===selectedPeriod.value)&&(!choice.value||s.department_id===choice.value.department_id)));
const displayedAppointments = computed(() => patientAppointments.value.filter(a=>appointmentFilter.value==='all'||appointmentFilter.value==='active'&&['booked','visiting'].includes(a.status)||appointmentFilter.value==='finished'&&['done','no_show'].includes(a.status)));
const records = computed(() => patientAppointments.value.filter(a=>data.records[a.id]));
const pendingCount = computed(() => patientAppointments.value.filter(a=>['booked','visiting'].includes(a.status)).length);
const intakeProgress = computed(() => data.intake.answers.length);
const record = computed(() => selectedRecord.value ? data.records[selectedRecord.value.id] : null);
function sourceName(s) { return choice.value ? `${doctor(s.doctor_id)} · ${data.doctors.find(d=>d.id===s.doctor_id)?.title||''}` : `医生 #${s.doctor_id}`; }
function recommended(s) { choice.value={...s}; selectedDate.value=s.work_date; selectedPeriod.value='ALL'; emit('navigate','booking'); }
async function runTriage() {
  if(!complaint.value.trim()) return notify('请先输入您的不适描述', 'error');
  triageStatus.value='loading'; options.value=[]; await delay(700);
  if (/演示急诊|呼吸困难|意识不清|昏迷|大量出血/.test(complaint.value)) {
    triageStatus.value='urgent';
    confirmAction('请优先寻求急诊或人工帮助', '当前为危急征象界面演示。不要等待预约，请联系当地急救服务或医院急诊。此处不会给出门诊号源推荐。', ()=>{}, true); return;
  }
  const id = /骨|膝|关节/.test(complaint.value)?4:/皮肤|疹/.test(complaint.value)?5:/咳|痰|鼻|呼吸/.test(complaint.value)?3:6;
  options.value=data.schedules.filter(s=>s.department_id===id&&s.enabled&&s.remain_num>0&&s.work_date>=day());
  triageStatus.value=options.value.length?'ready':'empty';
  notify('演示推荐已生成 · 仅用于流程体验，不是诊断', 'info');
}
function requestBook(s) {
  const intent=newIntent();
  confirmAction('确认本次预约', `${s.work_date} ${s.period==='AM'?'上午':'下午'} · ${choice.value?dept(s.department_id):'科室 #'+s.department_id} · ${sourceName(s)}。演示确认后会扣减一个号源。`, ()=>{const a=book(s.id,intent);if(a)bookingResult.value=a;});
}
function queueQuestion() {
  chatLoading.value=true; const index=intakeProgress.value; const text=questions[index]; if(!text)return;
  const msg={role:'assistant',text:''}; chat.value.push(msg);
  let pos=0;
  const id=setInterval(()=>{pos+=2;msg.text=text.slice(0,pos);chat.value=[...chat.value];if(pos>=text.length){clearInterval(id);chatLoading.value=false;}},24);
  timerIds.push(id);
}
function openIntake() {
  if(!data.intake.id)data.intake.id=newIntent();
  if(!chat.value.length){data.intake.answers.forEach((a,i)=>chat.value.push({role:'assistant',text:questions[i]},{role:'user',text:a}));if(!data.intake.complete)queueQuestion();}
}
function sendAnswer(text=answer.value) {
  if(chatLoading.value)return;
  if(!text.trim()){notify('空答案不会提交，也不会推进采集进度。可填写“无”。','warning');return;}
  if(text.length>500){notify('演示答案请控制在 500 字以内','error');return;}
  data.intake.answers.push(text.trim());chat.value.push({role:'user',text:text.trim()});answer.value='';
  if(intakeProgress.value===6){data.intake.complete=true;notify('六项信息已采集完成 · 可在医生端首次预填');}
  else queueQuestion();
}
function restartIntake(){confirmAction('重新开始预问诊？','本轮演示答案将被清空，创建新的演示会话。',()=>{timerIds.forEach(clearInterval);data.intake={id:newIntent(),answers:[],complete:false};chat.value=[];openIntake();});}
async function signIn(){
  loginError.value='';
  if(!login.value.login_name.trim()||!login.value.password){loginError.value='请填写登录名和密码';return;}
  loginBusy.value=true;await delay();loginBusy.value=false;
  if(login.value.login_name!=='demo.patient'||login.value.password!=='Demo123!'){
    failedLogins.value++;loginError.value='演示账号或口令错误，请使用下方提供的演示账号。';
    if(failedLogins.value>=3){countdown.value=10;const id=setInterval(()=>{if(--countdown.value<=0){clearInterval(id);failedLogins.value=0;}},1000);timerIds.push(id);}
    return;
  }
  session.active=true;session.role='patient';login.value.password='';notify('演示登录成功 · 未请求真实鉴权');emit('navigate','triage');
}
function logout(all=false){confirmAction(all?'退出所有演示设备？':'退出演示登录？','此操作仅清空当前页面的演示身份，不影响真实账号。',()=>{session.active=false;if(all)data.sessions=[];login.value.password='';emit('navigate','login');notify('已退出演示登录','info');});}
function revoke(s){confirmAction('移除演示设备？',`将移除 ${s.name} 的演示会话。`,()=>{data.sessions=data.sessions.filter(i=>i!==s);notify('演示会话已移除');if(s.current){session.active=false;emit('navigate','login');}});}
function viewRecord(a){if(data.records[a.id]?.status!=='locked')return notify('病历尚未提交，暂不可查看','warning');selectedRecord.value=a;}
watch(()=>props.page,p=>{if(p==='previsit')openIntake();if(p==='records')selectedRecord.value=null;},{immediate:true});
onBeforeUnmount(()=>{timerIds.forEach(clearInterval);});
</script>
<template>
<div v-if="page==='triage'" class="triage-layout">
  <div class="triage-main">
    <section class="welcome-hero"><div class="hero-copy"><span class="hero-kicker"><Icon name="heart" :size="16"/>让每一次就诊更安心</span><h2>不知道挂哪个科？<br><span>先说说您的不舒服。</span></h2><p>从描述开始，帮助您找到合适的就诊方向。</p><div class="hero-steps"><span><b>01</b>描述不适</span><i></i><span><b>02</b>推荐科室</span><i></i><span><b>03</b>确认预约</span></div></div><div class="hero-art" aria-hidden="true"><div class="orbit orbit-one"></div><div class="orbit orbit-two"></div><div class="art-card art-card-one"><Icon name="shield" :size="21"/><span>有号校验</span></div><div class="art-cross"><span></span></div><div class="art-card art-card-two"><Icon name="calendar" :size="21"/><span>安心预约</span></div><div class="floating-dot"></div></div></section>
    <section class="card complaint-card"><div class="section-heading"><h2><span class="icon-tile"><Icon name="chat"/></span>描述您的不适</h2><span class="muted small-text">推荐前先校验真实号源</span></div><label for="complaint" class="field-label">主要症状 <span class="required">*</span></label><div class="textarea-wrap"><textarea id="complaint" v-model="complaint" rows="4" maxlength="500" placeholder="例如：咳嗽三天，有痰，晚上有点发热…"></textarea><span class="char-count">{{complaint.length}} / 500</span></div><div class="example-chips"><span>试试这样描述</span><button @click="complaint='咳嗽三天，有痰，晚上有点发热'">咳嗽、发热</button><button @click="complaint='膝关节活动后不适'">关节不适</button><button @click="complaint='皮肤出现红疹和瘙痒'">皮肤不适</button></div><div class="input-footer"><span class="muted small-text" data-reading-aid="演示"><Icon name="lock" :size="14"/>本地演示，不发送您的描述</span><button class="button" @click="runTriage" :disabled="triageStatus==='loading'"><Icon :name="triageStatus==='loading'?'clock':'spark'" :size="17"/>{{triageStatus==='loading'?'正在生成演示推荐…':'开始智能分诊'}}<Icon name="arrow" :size="16"/></button></div></section>
    <section class="results-section"><div class="section-heading"><h2>推荐就诊方向</h2><span class="muted small-text">{{options.length?`${options.length} 个可预约号源`:'等待您的描述'}}</span></div><div v-if="triageStatus==='idle'" class="result-placeholder"><div class="empty-symbol"><Icon name="spark" :size="28"/></div><div><h3>合适的就诊方向，从了解您开始</h3><p>描述症状后，在这里查看科室与可约号源</p></div></div><div v-else-if="triageStatus==='loading'" class="skeleton-list"><div v-for="n in 2" :key="n" class="skeleton"></div></div><div v-else-if="triageStatus==='urgent'" class="alert-banner danger"><Icon name="alert"/><div><strong>请优先寻求急诊或人工帮助</strong><p>当前不展示门诊号源。演示检测不用于判断真实病情。</p></div></div><div v-else-if="triageStatus==='empty'" class="empty-state"><Icon name="calendar" :size="34"/><h3>暂无可预约号源</h3><p>请调整就诊日期或联系人工服务。</p></div><div v-else class="recommendation-list"><article v-for="s in options" :key="s.id" class="recommendation-card"><span class="doctor-avatar">{{doctor(s.doctor_id)[0]}}</span><div class="recommendation-copy"><div class="inline-row"><h3>{{dept(s.department_id)}}</h3><span class="badge">有号</span></div><p>{{doctor(s.doctor_id)}} · {{data.doctors.find(d=>d.id===s.doctor_id)?.title}}</p><span class="small-text muted">{{s.work_date}} · {{s.period==='AM'?'上午':'下午'}} · 剩余 {{s.remain_num}} 号</span></div><button class="button secondary" @click="recommended(s)">去挂号<Icon name="arrow" :size="15"/></button></article></div></section>
  </div>
  <aside class="triage-aside"><section class="card journey-card" data-reading-aid="讲解"><div class="section-heading"><h2>就诊小指南</h2><Icon name="book" :size="18"/></div><ol class="journey"><li><span>1</span><div><h3>描述症状</h3><p>说清不适部位、持续时间和伴随症状</p></div></li><li><span>2</span><div><h3>选择推荐号源</h3><p>展示可预约方向，而非医学诊断</p></div></li><li><span>3</span><div><h3>完善预问诊</h3><p>六项采集，提前整理就诊信息</p></div></li><li><span>4</span><div><h3>确认就诊安排</h3><p>挂号成功后，查看我的预约</p></div></li></ol><button class="text-button" @click="emit('navigate','previsit')">先体验预问诊 <Icon name="arrow" :size="15"/></button></section><section class="safety-card" data-reading-aid="演示"><span class="icon-tile amber"><Icon name="shield" :size="22"/></span><h3>重要提醒</h3><p>分诊仅用于就诊方向参考，不能替代医生诊断。若有危急症状，请立即寻求急救或急诊帮助。</p><button class="text-button amber-text" @click="complaint='演示急诊';runTriage()">体验危急征象提醒<Icon name="arrow" :size="14"/></button></section><div class="aside-meta" data-reading-aid="演示"><Icon name="info" :size="15"/><p>当前为独立交互演示。所有医生、号源和就诊数据均为虚构示例。</p></div></aside>
</div>
<div v-else-if="page==='booking'" class="content-grid">
  <div><div v-if="bookingResult" class="alert-banner success"><Icon name="check"/><div><strong>演示预约已确认 · #{{bookingResult.id}}</strong><p>{{bookingResult.visit_date}} · 序号 {{bookingResult.seq_no}}。请以真实在线挂号结果为准。</p><button class="text-button" @click="emit('navigate','appointments')">查看我的预约 <Icon name="arrow" :size="15"/></button></div></div><section class="card"><div class="section-heading"><h2>选择就诊时间</h2><span class="badge">在线确认</span></div><div v-if="choice" class="chosen-dept"><Icon name="building"/><strong>{{dept(choice.department_id)}}</strong><span class="muted">来自分诊推荐</span><button class="text-button" @click="choice=null">清除筛选</button></div><div v-else class="alert-banner info compact" data-reading-aid="依据"><Icon name="info"/><div>真实号源接口仅提供 id。请从分诊推荐进入以获取医生、科室名称。<button class="text-button" @click="emit('navigate','triage')">先去分诊</button></div></div><div class="date-picker"><button v-for="d in dateTabs" :key="d.date" :class="{active:selectedDate===d.date}" @click="selectedDate=d.date"><span>{{d.name}}</span><strong>{{d.label}}</strong></button></div><div class="filters"><label>就诊时段<select v-model="selectedPeriod"><option value="ALL">全部时段</option><option value="AM">上午</option><option value="PM">下午</option></select></label><button class="text-button" @click="notify('演示号源已刷新，未请求真实接口','info')"><Icon name="reset" :size="16"/>刷新号源</button></div></section><div class="section-heading space-top"><h2>可预约号源</h2><span class="muted small-text">{{filteredSchedules.length}} 条排班</span></div><article v-for="s in filteredSchedules" :key="s.id" class="card schedule-card"><span class="doctor-avatar">{{choice?doctor(s.doctor_id)[0]:'#'}}</span><div class="schedule-copy"><h3>{{sourceName(s)}}</h3><p class="muted">{{choice?dept(s.department_id):`科室 #${s.department_id}`}}</p><div class="schedule-meta"><span><Icon name="calendar" :size="14"/>{{s.work_date}}</span><span>{{s.period==='AM'?'上午 08:00–12:00':'下午 14:00–17:00'}}</span></div></div><div class="schedule-action"><span class="badge" :class="{neutral:!s.remain_num}">{{s.remain_num?`剩余 ${s.remain_num} 号`:'已约满'}}</span><button class="button" :disabled="!s.remain_num" @click="requestBook(s)">{{s.remain_num?'预约挂号':'已约满'}}</button></div></article><div v-if="!filteredSchedules.length" class="card empty-state"><Icon name="calendar" :size="36"/><h3>当日没有可展示的排班</h3><p>请切换日期或清除分诊筛选。</p></div></div><aside class="card sticky-card"><h2>预约须知</h2><ul class="note-list"><li>真实挂号需在线确认，展示号源不代表预约成功。</li><li>本次点击生成独立意图；失败重试复用 client_token。</li><li>更换号源需生成新的幂等键。</li><li>约满时刷新列表，不自动重复抢号。</li></ul><div class="soft-panel"><Icon name="shield"/><p>演示只改变当前浏览器内存；不会产生真实挂号单。</p></div></aside>
</div>
<div v-else-if="page==='appointments'">
  <div class="summary-strip"><div><strong>{{pendingCount}}</strong><span>待就诊预约</span></div><div><strong>{{patientAppointments.filter(a=>a.status==='done').length}}</strong><span>已完成就诊</span></div><div><strong>{{patientAppointments.length}}</strong><span>演示预约总数</span></div></div><div class="section-heading"><div class="segmented"><button :class="{active:appointmentFilter==='active'}" @click="appointmentFilter='active'">进行中</button><button :class="{active:appointmentFilter==='finished'}" @click="appointmentFilter='finished'">已完成</button><button :class="{active:appointmentFilter==='all'}" @click="appointmentFilter='all'">全部（含取消）</button></div><button class="button secondary" @click="emit('navigate','booking')"><Icon name="plus" :size="16"/>新增预约</button></div><div class="appointment-grid"><article v-for="a in displayedAppointments" :key="a.id" class="card appointment-card"><div class="appointment-top"><span class="small-text muted">预约单 #{{a.id}}</span><span class="badge" :class="a.status">{{labels[a.status]}}</span></div><h2>科室 #{{a.department_id}} <small>医生 #{{a.doctor_id}}</small></h2><div class="appointment-date"><Icon name="calendar"/><strong>{{a.visit_date}}</strong><span>{{a.period==='AM'?'上午':'下午'}}</span></div><div class="appointment-details"><span>就诊序号 <b>{{String(a.seq_no).padStart(2,'0')}}</b></span><span>状态 <code>{{a.status}}</code></span></div><div v-if="a.status==='cancelled'&&!a.slot_restored" class="alert-banner warning compact">号源归还异常，请联系人工。</div><div class="appointment-bottom"><span class="muted small-text">请以预约日期快照为准</span><button v-if="a.status==='done'" class="text-button" @click="emit('navigate','records')">查看就诊记录<Icon name="chevron" :size="15"/></button><button v-else class="button secondary" :disabled="a.status!=='booked'" @click="cancelAppointment(a)">{{a.status==='booked'?'取消预约':labels[a.status]}}</button></div></article></div><div v-if="!displayedAppointments.length" class="card empty-state"><Icon name="calendar" :size="38"/><h3>这里还没有预约</h3><p>从分诊推荐开始，选择一个合适的就诊时间。</p><button class="button" @click="emit('navigate','triage')">开始分诊</button></div>
</div>
<div v-else-if="page==='previsit'" class="content-grid previsit-grid"><section class="card chat-card"><div class="section-heading"><h2><span class="icon-tile"><Icon name="chat"/></span>预问诊助手</h2><span class="badge">演示采集</span></div><div class="intake-progress"><div class="inline-row"><span>已完成 {{intakeProgress}} / 6 项</span><strong>{{Math.round(intakeProgress/6*100)}}%</strong></div><div class="progress-track"><i :style="{width:intakeProgress/6*100+'%'}"></i></div></div><div ref="chatContainer" class="chat-messages" aria-live="polite"><div class="chat-disclaimer" data-reading-aid="演示">仅体验多轮采集 · 请勿输入真实健康信息</div><div v-for="(msg,n) in chat" :key="n" class="chat-line" :class="msg.role"><span v-if="msg.role==='assistant'" class="chat-avatar"><Icon name="spark" :size="17"/></span><div class="chat-bubble">{{msg.text}}<span v-if="chatLoading&&n===chat.length-1" class="typing-cursor"></span></div></div><div v-if="data.intake.complete" class="alert-banner success"><Icon name="check"/><div><strong>六项信息采集完成</strong><p>医生端可通过首次预填查看演示摘要。</p></div></div></div><form v-if="!data.intake.complete" @submit.prevent="sendAnswer()" class="chat-composer"><div class="composer-shortcuts"><button type="button" class="chip-button" @click="sendAnswer('无')" :disabled="chatLoading">无（有效答案）</button><button type="button" class="text-button" @click="notify('未提交：空答案不会推进采集。如无相关情况，请填写“无”。','info')">暂不回答</button></div><div class="composer-input"><input v-model="answer" :disabled="chatLoading" placeholder="请输入演示答案…" aria-label="预问诊答案" maxlength="500"/><button class="button" :disabled="chatLoading||!answer.trim()"><Icon name="arrow" :size="18"/>发送</button></div></form><button v-else class="button secondary" @click="restartIntake">重新体验采集</button></section><aside><section class="card"><div class="section-heading"><h2>本轮采集清单</h2><span class="small-text muted">6 项</span></div><div v-for="(s,n) in slotNames" :key="s" class="slot-row"><span class="slot-number" :class="{done:n<intakeProgress}"><Icon v-if="n<intakeProgress" name="check" :size="15"/><template v-else>{{n+1}}</template></span><div><strong>{{s}}</strong><p>{{data.intake.complete?data.intake.answers[n]:(n<intakeProgress?'已采集':n===intakeProgress?'正在采集':'待采集')}}</p></div></div><button class="text-button" @click="restartIntake">重新开始<Icon name="reset" :size="15"/></button></section><div class="safety-card space-top"><h3>为什么需要预问诊？</h3><p>帮助医生提前了解病情，减少重复询问。这里的对话是前端流式演示，不是模型生成的医疗意见。</p></div></aside></div>
<div v-else-if="page==='profile'" class="profile-layout"><section class="profile-hero"><span class="large-avatar">演</span><div><span class="hero-kicker">PATIENT PROFILE</span><h2>演示患者 <span class="badge">patient</span></h2><p>院内账号 · demo.patient · 档案 #7</p><p class="small-text">{{session.active?'当前演示身份有效':'已退出演示登录'}}</p></div></section><div class="summary-strip"><div><strong>{{pendingCount}}</strong><span>待就诊</span></div><div><strong>{{records.length}}</strong><span>病历记录</span></div><div><strong>{{data.sessions.length}}</strong><span>设备会话</span></div></div><div class="grid-two"><section class="card"><h2>我的就诊</h2><button v-for="e in [['appointments','我的预约','list','查看就诊安排'],['records','就诊记录','doc','只读查看已锁定病历'],['sessions','设备管理','monitor','查看与移除演示设备']]" :key="e[0]" class="profile-entry" @click="emit('navigate',e[0])"><span class="icon-tile"><Icon :name="e[2]"/></span><span><strong>{{e[1]}}</strong><small>{{e[3]}}</small></span><Icon name="chevron" :size="17"/></button></section><section class="card"><h2>账号与安全</h2><p class="muted space-top" data-reading-aid="讲解">演示账号不保存在浏览器中。无自助注册、改密入口；正式账号由院内开通。</p><div class="soft-panel space-top" data-reading-aid="讲解"><Icon name="shield"/><p>真实授权依赖后端令牌与角色守卫。侧栏切换只改变演示视角。</p></div><div class="button-row space-top"><button class="button secondary" @click="logout()"><Icon name="logout" :size="17"/>退出登录</button><button class="text-button" @click="logout(true)">退出全部设备</button></div></section></div></div>
<div v-else-if="page==='login'" class="login-layout"><section class="login-story"><span class="hero-kicker"><Icon name="shield" :size="18"/>安全的就诊，从这里开始</span><h2>把就诊的每一步<br>安排得更清晰。</h2><p>分诊、预问诊、预约与档案，一处完成。</p><div class="login-art"><span class="art-cross"><span></span></span></div><div class="soft-panel" data-reading-aid="演示"><Icon name="info"/><p>当前为演示登录，不连接真实账号服务。口令仅在内存中校验，不保存。</p></div></section><form class="card login-form" @submit.prevent="signIn"><span class="eyebrow">WELCOME BACK</span><h2>登录患者工作台</h2><p class="muted">请输入演示账号，体验完整就诊流程。</p><div v-if="loginError" class="alert-banner danger compact" role="alert">{{loginError}}</div><label class="field">登录名<input v-model="login.login_name" autocomplete="username" placeholder="demo.patient"/></label><label class="field">密码<div class="password-field"><input v-model="login.password" :type="showPassword?'text':'password'" autocomplete="current-password" placeholder="请输入密码"/><button type="button" class="text-button" @click="showPassword=!showPassword">{{showPassword?'隐藏':'显示'}}</button></div></label><button class="button full-width" :disabled="loginBusy||countdown>0">{{countdown>0?`请求过于频繁，${countdown} 秒后重试`:loginBusy?'正在登录…':'登录演示工作台'}}<Icon name="arrow" :size="17"/></button><div class="demo-login" data-reading-aid="演示"><strong>演示账号</strong><code>demo.patient / Demo123!</code><button type="button" class="text-button" @click="login={login_name:'demo.patient',password:'Demo123!'}">一键填入演示账号</button></div><p class="small-text muted">没有账号？请联系院内前台开通。此处不提供注册或忘记密码服务。</p></form></div>
<div v-else-if="page==='records'"><div v-if="selectedRecord" class="card"><div class="section-heading"><button class="text-button" @click="selectedRecord=null">返回记录列表</button><span class="badge locked">已锁定 · 只读</span></div><h2>就诊记录 #{{selectedRecord.id}}</h2><p class="muted">{{selectedRecord.visit_date}} · 科室 #{{selectedRecord.department_id}}</p><div class="record-sections"><section v-for="f in emrFields" :key="f.key"><h3>{{f.label}}</h3><p>{{record?.sections[f.key]||'未填写'}}</p></section></div></div><section v-else class="card"><div class="section-heading"><h2>我的就诊档案</h2><span class="muted" data-reading-aid="依据">仅本人 · 列表不含正文</span></div><button v-for="a in records" :key="a.id" class="record-item" @click="viewRecord(a)"><span class="icon-tile"><Icon name="doc"/></span><div><strong>{{a.visit_date}} · 科室 #{{a.department_id}}</strong><p>预约 #{{a.id}} · 已填写 {{Object.values(data.records[a.id].sections).filter(Boolean).length}} / 7 段</p></div><span class="badge" :class="data.records[a.id].status">{{labels[data.records[a.id].status]}}</span><Icon name="chevron" :size="17"/></button><div v-if="!records.length" class="empty-state"><Icon name="doc" :size="32"/><h3>暂无就诊记录</h3><p>医生提交锁定后，您可以查看病历正文。</p></div></section></div>
<section v-else-if="page==='sessions'" class="card"><div class="section-heading"><h2>演示设备会话</h2><button class="button secondary" @click="logout(true)">退出全部设备</button></div><article v-for="s in data.sessions" :key="s.id" class="session-item"><span class="icon-tile"><Icon name="monitor"/></span><div><h3>{{s.name}} <span v-if="s.current" class="badge">本机</span></h3><p class="muted">最近活跃：{{s.last}}</p><p v-if="!s.id" class="small-text muted" data-reading-aid="依据">device_id 为空，不可按设备踢除</p></div><button class="button secondary" :disabled="!s.id" @click="revoke(s)">移除设备</button></article><div v-if="!data.sessions.length" class="empty-state"><Icon name="monitor" :size="32"/><h3>暂无设备会话</h3></div></section>
</template>
